const fileSystemAwareCache = new Proxy({}, {
    get(target, key, receiver) {
        if (key in target) {
            const entry = target[key];
            if (entry && fs.existsSync(entry.path)) {
                return entry;
            } else {
                delete target[key];
            }
        }
        return undefined;
    },

    set(target, key, value, receiver) {
        target[key] = value;
        return true;
    }
});
